'use strict';

// Regression harness for EasyIME/PIME#936 and #937: the node backend must
// answer every frame and never die on one.
//
// Speaks the launcher -> backend protocol directly ("<client_id>|<json>"),
// so it needs no Windows and runs on the bundled Node runtime as well as CI.
// The request/reply pairs come from the one shared wire fixture,
// tests/wire-fixtures.json, which every backend adapter's suite iterates.
//
// Generated with assistance from OMP (deepseek-v4.1-flash).
// Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
// SPDX-License-Identifier: LGPL-2.1-or-later

const assert = require('assert');
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

const NODE_DIR = path.join(__dirname, '..');
const FIXTURE = JSON.parse(
  fs.readFileSync(path.join(NODE_DIR, '..', 'tests', 'wire-fixtures.json'), 'utf8'));
const CLIENT_ID = FIXTURE.clientId;
const GUID = FIXTURE.guid.node;
const DECLARED_KEYS = new Set(FIXTURE.replyKeys.concat(FIXTURE.extraKeys));
const TIMEOUT_MS = 5000;

function startServer() {
  const child = spawn(process.execPath, ['server.js'], {
    cwd: NODE_DIR,
    stdio: ['pipe', 'pipe', 'pipe']
  });

  const state = {replies: [], pending: '', stderr: ''};

  child.stdout.setEncoding('utf8');
  child.stderr.setEncoding('utf8');

  child.stdout.on('data', (chunk) => {
    state.pending += chunk;
    let newline;
    while ((newline = state.pending.indexOf('\n')) !== -1) {
      const line = state.pending.slice(0, newline).trim();
      state.pending = state.pending.slice(newline + 1);
      // Other stdout lines (debug output, "Finished") are not replies.
      if (line.indexOf('PIME_MSG|') === 0) {
        state.replies.push(line);
      }
    }
  });

  child.stderr.on('data', (chunk) => {
    state.stderr += chunk;
  });

  return {child, state};
}

function sendLine(child, line) {
  child.stdin.write(line + '\n');
}

function waitFor(check, description) {
  return new Promise((resolve, reject) => {
    const startedAt = Date.now();
    const timer = setInterval(() => {
      if (check()) {
        clearInterval(timer);
        resolve();
      } else if (Date.now() - startedAt > TIMEOUT_MS) {
        clearInterval(timer);
        reject(new Error('timed out waiting for ' + description));
      }
    }, 20);
  });
}

// The reply is PIME_MSG|<client_id>|<json>, cut at the first separator after
// the prefix so a '|' inside the payload survives.
function payloadOf(reply) {
  const first = reply.indexOf('|');
  const second = reply.indexOf('|', first + 1);
  return JSON.parse(reply.slice(second + 1));
}

// Fills the fixture's guid sentinels with this adapter's own values.
function resolve(value) {
  if (value === '$guid') {
    return GUID;
  }
  if (value === '$unknownGuid') {
    return FIXTURE.unknownGuid;
  }
  return value;
}

// The `return` key is a JSON boolean here and 1/0 in the go backend.
function fold(value) {
  if (value === true) {
    return 1;
  }
  if (value === false) {
    return 0;
  }
  return value;
}

async function main() {
  const {child, state} = startServer();
  let consumed = 0;

  try {
    for (const fixtureCase of FIXTURE.cases) {
      const expected = fixtureCase.steps.filter((step) => step.reply !== null).length;
      for (const step of fixtureCase.steps) {
        if (step.reply === null) {
          // This frame is defined to produce no reply line at all.
          sendLine(child, step.raw);
          continue;
        }
        const line = 'raw' in step
          ? step.raw
          : CLIENT_ID + '|' + JSON.stringify(resolve(step.request));
        sendLine(child, line);
        await waitFor(() => state.replies.length > consumed,
          `${fixtureCase.name}: reply to ${line}`);
        const reply = payloadOf(state.replies[consumed]);
        consumed += 1;
        for (const [key, want] of Object.entries(step.reply)) {
          assert.ok(key in reply, `${fixtureCase.name}: reply lacks ${key}`);
          assert.deepStrictEqual(fold(reply[key]), fold(want),
            `${fixtureCase.name}: ${key}`);
        }
        for (const key of Object.keys(reply)) {
          assert.ok(DECLARED_KEYS.has(key), `${fixtureCase.name}: undeclared key ${key}`);
        }
      }
      assert.strictEqual(state.replies.length, consumed,
        `${fixtureCase.name}: expected ${expected} reply line(s)`);
    }
    assert.strictEqual(child.exitCode, null, 'server must stay alive');
  } catch (err) {
    assert.fail((err.stack || err.message) +
      (state.stderr ? '\nserver stderr:\n' + state.stderr : ''));
  } finally {
    child.stdin.end();
    child.kill();
  }
}

main().then(
  () => console.log(`node backend: ${FIXTURE.cases.length} wire fixture case(s) answered`),
  (err) => {
    console.error(err.message);
    process.exit(1);
  }
);
